/**
 * @method
 * @name scwin.tx_fn_Delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/support/eduRspnStaff.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16505.tx_fn_Delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param _submitYn
 * @returns
 * @hidden N
*/
scwin.register = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!scwin.chk()) {
        return;
    }
    const frm = (document.eduForm || { elements: [] });
    frm.action = 'eduRspnStaff.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerResponsibilityEducation');
    $c.util.getComponent('dma_RegisterReq').set('SCREN_PROCES_TP_CD', "02");
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


