/**
 * @method
 * @name scwin.deleteRegisterReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param _disclsEduApplSeq _submitYn
 * @returns
 * @hidden N
*/
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _submitYn) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        const frm = (document.eduForm || { elements: [] });
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        frm.action = 'eduRspnStaff.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeResponsibilityEducation');
        $c.util.getComponent('dma_RegisterReq').set('SCREN_PROCES_TP_CD', "04");
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


